                    [ 'Metal keyrings, workshop personalisation', 'F2', 'Portable, 50 MP camera, 5 W IR laser for metal', 'Compact, not for cutting full sheets' ],
                    [ 'Advent calendars, acrylic, large batches', 'P3', '80 W CO₂, 914 × 457 mm bed, conveyor feeder', 'Needs space and extraction to the outside' ],
